CREATE TABLE IF NOT EXISTS audit_records (id text PRIMARY KEY, organization_id text NOT NULL, project_id text NOT NULL, environment_id text NOT NULL, transaction_id text NOT NULL, sequence integer NOT NULL, category text NOT NULL, record_hash text NOT NULL, record jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,project_id,environment_id,transaction_id,sequence));
ALTER TABLE audit_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_record_tenant_isolation ON audit_records USING (organization_id=current_setting('interweave.organization_id',true) AND project_id=current_setting('interweave.project_id',true) AND environment_id=current_setting('interweave.environment_id',true)) WITH CHECK (organization_id=current_setting('interweave.organization_id',true) AND project_id=current_setting('interweave.project_id',true) AND environment_id=current_setting('interweave.environment_id',true));
CREATE OR REPLACE FUNCTION reject_audit_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'audit records are immutable'; END $$;
CREATE TRIGGER audit_records_no_update_delete BEFORE UPDATE OR DELETE ON audit_records FOR EACH ROW EXECUTE FUNCTION reject_audit_mutation();
